<template><div class="page"><div class="head"><div><span>家庭对账凭证</span><h1>购药费用分析</h1><p>按年、月、周、日、平台、线上线下和购药时段查看次数与金额。</p></div><el-button type="primary" @click="exportExcel">导出完整Excel明细</el-button></div><el-card shadow="never" class="filters"><el-select v-model="userId" clearable placeholder="全部老人" @change="loadAll"><el-option v-for="u in users" :key="u.userId" :label="u.realName+'（'+u.username+'）'" :value="u.userId"/></el-select><el-segmented v-model="type" :options="options" @change="loadChart"/></el-card><section class="metrics"><article><small>累计购药支出</small><strong>¥{{money(summary.total_amount)}}</strong></article><article><small>购药订单/次数</small><strong>{{summary.order_count||0}}次</strong></article><article><small>线上购药金额</small><strong>¥{{money(summary.online_amount)}}</strong></article><article><small>线下购药金额</small><strong>¥{{money(summary.offline_amount)}}</strong></article></section><el-card shadow="never" class="chart-card"><div ref="chartRef" class="chart"></div></el-card><el-card shadow="never"><template #header><b>{{currentLabel}}明细</b></template><el-table :data="data" border stripe><el-table-column :prop="keyField" :label="currentLabel"/><el-table-column label="购药金额"><template #default="{row}"><b class="amount">¥{{money(row.total_amount)}}</b></template></el-table-column><el-table-column label="购药次数"><template #default="{row}">{{row.count||0}}次</template></el-table-column><el-table-column label="次均花费"><template #default="{row}">¥{{money(row.average_amount)}}</template></el-table-column></el-table></el-card></div></template>
<script setup>import{ref,computed,onMounted,nextTick}from'vue';import*as echarts from'echarts';import{getUserList}from'../../api/user';import{getYearlyStats,getMonthlyStats,getWeeklyStats,getDailyStats,getPlatformStats,getChannelStats,getTimeBucketStats,getExpenseSummary}from'../../api/purchase';import{downloadFile}from'../../utils/download';import{ElMessage}from'element-plus';const users=ref([]),userId=ref(null),type=ref('monthly'),data=ref([]),summary=ref({}),chartRef=ref(null);let chart;const options=[{label:'年度',value:'yearly'},{label:'月度',value:'monthly'},{label:'周度',value:'weekly'},{label:'日度',value:'daily'},{label:'平台',value:'platform'},{label:'线上/线下',value:'channel'},{label:'购药时段',value:'time'}];const meta={yearly:['year','年份'],monthly:['month','月份'],weekly:['week','周'],daily:['day','日期'],platform:['name','购药平台'],channel:['name','购买渠道'],time:['name','购药时段']};const keyField=computed(()=>meta[type.value][0]),currentLabel=computed(()=>meta[type.value][1]),money=v=>Number(v||0).toFixed(2);const loaders={yearly:getYearlyStats,monthly:getMonthlyStats,weekly:getWeeklyStats,daily:id=>getDailyStats(id,120),platform:getPlatformStats,channel:getChannelStats,time:getTimeBucketStats};const loadChart=async()=>{const r=await loaders[type.value](userId.value);data.value=r.data||[];await nextTick();render()};const loadAll=async()=>{const r=await getExpenseSummary(userId.value);summary.value=r.data||{};loadChart()};const render=()=>{if(!chart)chart=echarts.init(chartRef.value);const labels=data.value.map(x=>x[keyField.value]),amounts=data.value.map(x=>Number(x.total_amount||0)),counts=data.value.map(x=>Number(x.count||0));chart.setOption({tooltip:{trigger:'axis'},legend:{data:['购药金额','购药次数']},grid:{left:55,right:55,bottom:55},xAxis:{type:'category',data:labels,axisLabel:{rotate:labels.length>8?35:0}},yAxis:[{type:'value',name:'金额(元)'},{type:'value',name:'次数'}],series:[{name:'购药金额',type:'bar',data:amounts,itemStyle:{color:'#397c64',borderRadius:[6,6,0,0]}},{name:'购药次数',type:'line',yAxisIndex:1,smooth:true,data:counts,itemStyle:{color:'#e39a45'}}]},true)};const exportExcel=async()=>{await downloadFile('/export/purchase',{userId:userId.value},'购药费用凭证明细.xlsx');ElMessage.success('Excel已导出')};onMounted(async()=>{const r=await getUserList('ELDER');users.value=r.data||[];await loadAll();window.addEventListener('resize',()=>chart?.resize())})</script>
<style scoped>.page{max-width:1200px;margin:auto}.head{display:flex;justify-content:space-between;align-items:end;margin-bottom:16px}.head span{color:#3a8066;font-weight:700}.head h1{margin:5px 0}.head p{margin:0;color:#75817a}.filters{margin-bottom:14px}.filters :deep(.el-card__body){display:flex;gap:14px;justify-content:space-between}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:14px}.metrics article{padding:18px;border-radius:15px;background:#fff;border:1px solid #e4ebe6}.metrics small,.metrics strong{display:block}.metrics small{color:#77827a}.metrics strong{font-size:25px;color:#34734e;margin-top:8px}.chart-card{margin-bottom:14px}.chart{height:430px}.amount{color:#34734e}@media(max-width:800px){.head{align-items:stretch;flex-direction:column;gap:12px}.filters :deep(.el-card__body){align-items:stretch;flex-direction:column;overflow-x:auto}.metrics{grid-template-columns:1fr 1fr}.chart{height:350px}}@media(max-width:430px){.metrics{grid-template-columns:1fr}.metrics strong{font-size:22px}}</style>
